pitch  = 83.8;
boss_h = 4.1;
screw  = 3.2;

$fn = 48;

base_t = 3;
boss_d = screw + 5;

difference() {
    union() {
        translate([-plate / 2, -plate / 2, 0]) cube([plate, plate, base_t]);
        for (x = [-pitch / 2, pitch / 2])
            for (y = [-pitch / 2, pitch / 2])
                translate([x, y, 0]) cylinder(h = base_t + boss_h, d = boss_d);
    }
    for (x = [-pitch / 2, pitch / 2])
        for (y = [-pitch / 2, pitch / 2])
            translate([x, y, -1]) cylinder(h = base_t + boss_h + 2, d = screw);
}

